export function getMasterSeaRoute(startId, destId) {
  const directKey = `${startId}-${destId}`;
  if (MASTER_SEA_ROUTES[directKey]) {
    return MASTER_SEA_ROUTES[directKey];
  }
  const revKey = `${destId}-${startId}`;
  if (MASTER_SEA_ROUTES[revKey]) {
    const orig = MASTER_SEA_ROUTES[revKey];
    return {
      coordinates: [...orig.coordinates].reverse(),
      distanceNM: orig.distanceNM,
      passages: orig.passages || [],
      waypointsManifest: orig.waypointsManifest ? [...orig.waypointsManifest].reverse() : [],
    };
  }
  return null;
}
